import { CardDescription, CardHeader, CardTitle } from '@clossys/designer-ui';

/** The `header` input of `sections.studio.page-header`: the page's title and its one-line purpose. */
export interface PageHeaderInput {
  title: string;
  description?: string;
}

/** `sections.studio.page-header`: the head of every Studio page, the stock shadcn card header. */
export default function PageHeaderSection({ header }: { header: PageHeaderInput }) {
  return <CardHeader data-studio-section="page-header">
    <CardTitle role="heading" aria-level={1} className="text-xl">{header.title}</CardTitle>
    {header.description ? <CardDescription>{header.description}</CardDescription> : null}
  </CardHeader>;
}

{
  "$schema": "https://ui.shadcn.com/schema/registry-item.json",
  "name": "studio-page-header",
  "type": "registry:block",
  "title": "Page Header",
  "description": "The head of every Studio page: its title and one-line purpose, the stock shadcn card header.",
  "author": "Clossys",
  "dependencies": [],
  "registryDependencies": [
    "card"
  ],
  "files": [
    {
      "path": "index.tsx",
      "type": "registry:component",
      "target": "studio/sections/studio-page-header/index.tsx"
    }
  ]
}
